from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Initialize an empty list to store the separated groups
    separated_groups = []

    # Loop through the input string to identify individual groups of nested parentheses
    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while count != 0:
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                j += 1
            separated_groups.append(paren_string[i:j])
            i = j
        else:
            i += 1

    return separated_groups

